import{shoreZ as l}from"./city.min.js";export const WHEEL={x:-266,out:110,turn:14,scale:2.5,pier:{width:70,past:26,back:36},deck:4,platform:5.6,hub:32.6,radius:23.8,tube:.8,apart:4.8,gondolas:24,gondola:{width:2.8,height:3.2,depth:2.6},legs:{spread:13,splay:6.5},spokes:12,opens:10,closes:23,stop:12,board:{steps:6,move:7,hold:10},ride:{turns:2,seconds:240,ease:15},lamps:96,show:40,fade:4,dusk:.25};export function wheelSite(n=[.35,.9],t=WHEEL){const o=l(t.x),s=o-t.out,r=Math.atan2(n[0]-t.x,n[1]-s)+t.turn*Math.PI/180;return{x:t.x,z:s,shore:o,start:s+t.pier.back,end:s-t.pier.past,yaw:r}}export function drawnHeight(n,t=WHEEL){return t.deck+(n-t.deck)*t.scale}export function wheelOpen(n,t=WHEEL){const o=n.getHours()+n.getMinutes()/60+n.getSeconds()/3600;return o>=t.opens&&o<t.closes}const h=n=>{const t=Math.min(1,Math.max(0,n));return t*t*(3-2*t)};function x(n,t,o,s){const r=t/(o-s);return n<=0?0:n<s?r*n*n/(2*s):n<o-s?r*(n-s/2):n<o?t-r*(o-n)*(o-n)/(2*s):t}export function wheelCycle(n=WHEEL){const{steps:t,move:o,hold:s}=n.board,r=t*(o+s),a=360/n.gondolas;return{boarding:r,seconds:r+n.ride.seconds,bay:a,degrees:t*a+360*n.ride.turns}}export function wheelTurn(n,t=WHEEL){const o=wheelCycle(t),s=Math.floor(n/o.seconds);let r=n-s*o.seconds;const a=s*o.degrees,{steps:c,move:i,hold:e}=t.board;if(r<o.boarding){const p=Math.floor(r/(i+e));return a+(p+h((r-p*(i+e))/i))*o.bay}r-=o.boarding;const{turns:u,seconds:d,ease:f}=t.ride;return a+c*o.bay+x(r,360*u,d,f)}export function wheelMoving(n,t=WHEEL){const o=wheelCycle(t),s=n-Math.floor(n/o.seconds)*o.seconds;if(s>=o.boarding)return!0;const{move:r,hold:a}=t.board;return s-Math.floor(s/(r+a))*(r+a)<r}export function wheelStart(n,t,o=WHEEL){const s=wheelCycle(o).boarding;return{running:n,since:t-s,base:-wheelTurn(s,o),angle:0,stopping:null}}function M(n,t){const s=Math.max(0,n-.05);return(wheelTurn(n+.05,t)-wheelTurn(s,t))/(n+.05-s)}export function wheelStep(n,t,o,s=!1,r=WHEEL){if(s)return n;if(n.stopping){const{at:a,from:c,speed:i}=n.stopping,e=Math.min(Math.max(0,o-a),r.stop),u=c+i*(e-e*e/(2*r.stop));return t?{running:!0,since:o,base:u,angle:u,stopping:null}:e>=r.stop?{...n,running:!1,angle:u,stopping:null}:{...n,angle:u}}if(n.running){const a=o-n.since,c=n.base+wheelTurn(a,r);if(t)return{...n,angle:c};const i=M(a,r);return i<=0?{...n,running:!1,angle:c}:{...n,angle:c,stopping:{at:o,from:c,speed:i}}}return t?{running:!0,since:o,base:n.angle,angle:n.angle,stopping:null}:n}export function seatAt(n,t,o=WHEEL){const s=(t+n*360/o.gondolas)*Math.PI/180,r=[o.radius*Math.cos(s),o.radius*Math.sin(s)];return{pivot:r,middle:[r[0],r[1]-o.gondola.height/2]}}const b=n=>n<=.04045?n/12.92:((n+.055)/1.055)**2.4;export function hsv(n,t,o){const s=r=>{const a=(r+n*6)%6;return o-o*t*Math.max(0,Math.min(a,4-a,1))};return[s(5),s(3),s(1)]}export const SHOWS=[(n,t,o)=>hsv((n/t+o/40)%1,.8,1),(n,t,o)=>hsv(.5+.08*Math.sin(2*Math.PI*(2*n/t-o/12)),.75,.85+.15*Math.sin(2*Math.PI*(n/t+o/12))),(n,t,o)=>hsv(o/60%1,.7,.8+.2*Math.sin(2*Math.PI*o/6))];export function wheelColors(n,t=WHEEL.lamps,o=new Float32Array(t*3),s=WHEEL){const r=n/s.show,a=Math.floor(r),c=(r-a)*s.show,i=h((c-(s.show-s.fade))/s.fade),e=SHOWS[(a%SHOWS.length+SHOWS.length)%SHOWS.length],u=SHOWS[((a+1)%SHOWS.length+SHOWS.length)%SHOWS.length];for(let d=0;d<t;d++){const f=e(d,t,n),p=i>0?u(d,t,n):f;for(let g=0;g<3;g++)o[d*3+g]=b(f[g]+(p[g]-f[g])*i)}return o}export function wheelLit(n,t,o=WHEEL){return t>o.dusk&&wheelOpen(n,o)}
